const $ = (selector, root = document) => root.querySelector(selector);
const escape = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const main = $('#main');
const dialog = $('#detail-dialog');
const content = $('#dialog-content');
let data, glossary, beginner = false, category = 'All', signal = 'all', returnDialog = null;
try { beginner = localStorage.getItem('frontier-simplified-vocabulary') === 'true'; } catch {}
const categories = ['All', 'Incidents', 'Capabilities', 'Governance', 'AI R&D', 'Cyber', 'Monitoring', 'Model proliferation', 'CBRN'];
const direction = {worsening:['↗','More concerning','amber'],improving:['↘','Safety signal','mint'],mixed:['↔','Mixed signal','muted']};
const date = value => new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}).format(new Date(value+'T12:00:00Z'));
function rich(text) { return escape(text).replace(/\[\[([^\]]+)\]\]/g,(_,term)=>`<button class="jargon" data-term="${escape(term.toLowerCase())}" aria-label="Define ${escape(term)}">${term}<span aria-hidden="true">ⓘ</span></button>`); }
function sources(event) { return event.sources.map(s=>`<a class="source-link" href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">${escape(s.publisher)} <span>↗</span><small>${escape(s.title)}</small></a>`).join(''); }
function openDialog(html) { content.innerHTML=html; if(!dialog.open) dialog.showModal(); dialog.scrollTop=0; $('.close-dialog').focus(); }
function showEvent(id, worry = false) {
 const e=data.events.find(x=>x.id===id); if(!e)return;
 const d=direction[e.direction];
 openDialog(`<p class="eyebrow">${date(e.date)} · ${escape(e.category)} · ${data.mode==='demo'?'RESEARCH PREVIEW':'REVIEWED NOTE'}</p><h2 id="dialog-title">${escape(e.title)}</h2><div class="event-meta"><span class="${d[2]}">${d[0]} ${d[1]}</span><span>${escape(e.evidence)}</span></div><p class="lead">${rich(beginner?e.summary_beginner:e.technical_summary)}</p><div class="interpretation"><section><p class="eyebrow">WHAT HAPPENED</p><p>${rich(e.summary_beginner)}</p></section><section><p class="eyebrow">WHAT IT MEANS <span class="small-note">/ INTERPRETATION</span></p><p>${rich(e.why_it_matters)}</p></section><section class="limit"><p class="eyebrow">WHAT IT DOESN’T MEAN</p><p>${rich(e.what_it_doesnt_mean)}</p></section><section><p class="eyebrow">WHAT WOULD RAISE CONCERN</p><p>${rich(e.what_would_raise_concern)}</p></section></div><details class="technical"><summary>Technical explanation</summary><p>${rich(e.technical_summary)}</p><p class="small-note">${escape(e.evidenceNote)}</p></details><details class="worry" ${worry?'open':''}><summary>How worried should I actually be? <span>+</span></summary><div class="worry-content"><h3 class="amber">More concerning because</h3><p>${rich(e.why_it_matters)}</p><h3 class="mint">Less concerning because</h3><p>${rich(e.less_concerning)}</p><h3>Still not established by this report</h3><p>Durable independent resource control, persistent self-replication, or successful resistance to a determined human shutdown.</p><div class="takeaway">${rich(e.conclusion)}</div></div></details><h3>Sources</h3><p class="small-note">${escape(e.evidenceNote)}</p>${sources(e)}<p class="small-note">${data.mode==='demo'?'AI-assisted summary for interface demonstration. Human editorial review is pending.':'Reviewed by '+escape(e.review.reviewedBy)+' on '+escape(e.review.reviewedAt)+'.'}</p>`);
 if(worry)$('.worry',content).scrollIntoView({block:'start',behavior:'instant'});
}
function showPathway(id) {
 const p=data.pathways.find(x=>x.id===id);if(!p)return;
 const events=data.events.filter(e=>p.eventIds.includes(e.id));
 openDialog(`<p class="eyebrow">RISK PATHWAY · ${data.mode==='demo'?'ILLUSTRATIVE STATUS':'REVIEWED STATUS'}</p><h2 id="dialog-title">${escape(p.name)}</h2><p class="lead">${escape(p.question)}</p><span class="pill amber">${escape(p.status)} ${escape(p.trend)}</span><h3>What this means</h3><p>${rich(p.meaning)}</p><h3>Why it matters</h3><p>${rich(p.care)}</p><div class="limit standalone"><p class="eyebrow">WHAT HAS NOT BEEN ESTABLISHED</p><p>${rich(p.notDemonstrated)}</p></div><h3>Relevant evidence</h3>${events.map(e=>`<button class="related" data-event="${e.id}"><span><small>${date(e.date)}</small>${escape(e.title)}</span><span>↗</span></button>`).join('')}<h3>Direction to watch</h3><p>${escape(p.interpretation)} This is a qualitative reading of the selected sources, not a complete assessment of the field.</p>`);
}
function showOutlook() {
 const o=data.outlook;
 openDialog(`<p class="eyebrow">ASSESSMENT TRANSPARENCY · ${data.mode==='demo'?'DEMONSTRATION':'REVIEWED'}</p><h2 id="dialog-title">Why ${escape(o.level.toLowerCase())}?</h2>${data.mode==='demo'?'<div class="demo-note">This rating is illustrative. The source set ends in August 2025 and is not a current risk advisory.</div>':''}<p>${escape(o.summary)}</p><h3>Supporting evidence</h3>${data.events.filter(e=>o.basis.includes(e.id)).map(e=>`<button class="related" data-event="${e.id}"><span><small>${escape(e.evidence)}</small>${escape(e.title)}</span><span>↗</span></button>`).join('')}<h3 class="amber">What would make the outlook worse?</h3><p>${escape(o.moreConcerning)}</p><h3 class="mint">What would make it better?</h3><p>${escape(o.lessConcerning)}</p><h3>What remains uncertain?</h3><p>How test results transfer to everyday use, how reliably safeguards hold up, and how capability changes interact. We do not convert these uncertainties into a precise catastrophe probability.</p><a class="text-link" href="#methodology" data-close>Methodology ↗</a>`);
}
function showTerm(term) {
 const g=glossary[term];if(!g)return;
 if(dialog.open && !returnDialog) returnDialog=content.innerHTML;
 openDialog(`<p class="eyebrow">GLOSSARY</p><h2 id="dialog-title">${escape(term.charAt(0).toUpperCase()+term.slice(1))}</h2><p class="lead">${escape(g.definition)}</p><h3>Think of it like…</h3><p>${escape(g.analogy)}</p>${returnDialog?'<button class="text-link" data-action="back-dialog">← Back to the evidence</button>':''}`);
}
function heading(title){return `<section class="page-heading"><h1>${title}</h1></section>`;}
function demoNote(){return data.mode==='demo'?'<div class="demo-note"><span class="demo-label">PREVIEW</span><span>Real research, illustrative assessments. Sources: February–August 2025. Not a current risk advisory.</span></div>':'';}
function pathwayCards(){return data.pathways.map((p,i)=>`<button class="pathway-card" data-pathway="${p.id}"><span class="card-top"><span class="card-number">0${i+1}</span><span class="pathway-status">${escape(p.status)} ${escape(p.trend)}</span></span><h3>${escape(p.name)}</h3><p>${escape(p.question)}</p><span class="card-bottom">${escape(p.interpretation)}<span>↗</span></span></button>`).join('');}
function eventRows(events){return events.map(e=>{const d=direction[e.direction];return `<article class="event-row"><div class="event-date"><span>${new Date(e.date+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',timeZone:'UTC'})}</span><strong>${e.date.slice(8)}</strong><small>${e.date.slice(0,4)}</small></div><div class="event-body"><div class="event-meta"><span class="${d[2]}">${d[0]} ${d[1]}</span><span>${escape(e.category)}</span><span>${escape(e.evidence)}</span></div><h3><button data-event="${e.id}">${escape(e.title)}</button></h3><p>${rich(beginner?e.summary_beginner:e.technical_summary)}</p><div class="event-bottom"><div>${e.pathways.map(id=>`<button class="tag" data-pathway="${id}">${escape(data.pathways.find(p=>p.id===id).name)}</button>`).join('')}</div><button class="worry-link" data-worry="${e.id}">How worried should I be? <span>↗</span></button></div></div></article>`;}).join('');}
function timelineMarkup(){return `<section id="timeline"><div class="section-head"><div><h2>Research timeline</h2></div><span class="small-note">${data.events.length} research notes · ${date(data.asOf)}</span></div><div class="timeline-controls"><div class="filters" role="group" aria-label="Filter notes by category">${categories.map(c=>`<button class="filter ${c===category?'selected':''}" data-filter="${c}" aria-pressed="${c===category}">${c}</button>`).join('')}</div><div class="signal-filter"><label for="signal-filter">Signal direction</label><select id="signal-filter"><option value="all">All signals</option><option value="worsening">Capability & risk</option><option value="improving">Safety & control</option><option value="mixed">Mixed signals</option></select></div></div><p id="result-count" class="small-note" role="status" aria-live="polite"></p><div id="event-list"></div></section>`;}
const stages=[
 ['Tool use','Documented in selected research','An AI uses an external tool, such as a search engine or code runner.','Tool access lets outputs become actions. Permissions set the boundaries.','shade'],
 ['Autonomous multi-step work','Documented in selected research','An agent links several actions to pursue a goal without approval at every step.','Longer chains of work create more opportunities for both useful results and cascading mistakes.','long-tasks'],
 ['Circumvents obstacles','Limited experimental evidence','A system finds an alternative route when its first approach fails.','Useful problem solving becomes concerning when the obstacle is a safety constraint. Simulated harmful choices are evidence about behavior, not a verified technical escape.','agentic'],
 ['Crosses intended boundaries','Not established by this source set','A system reaches information or capabilities it was meant to be unable to access.','Distinguish a permission violation from a content-filter bypass. Evidence must specify which boundary failed.','classifiers'],
 ['Acquires outside resources','Not established by this source set','A system obtains additional compute, accounts, or tools beyond its assigned environment.','Authorization matters: an approved cloud task is different from unapproved resource acquisition.',null],
 ['Establishes external persistence','Not established by this source set','A system maintains an operating foothold outside its original environment.','A temporary connection is insufficient. Continued operation needs direct evidence.',null],
 ['Replicates independently','Not established by this source set','A system makes and runs a functioning copy without a human carrying out the critical steps.','A simulated replication task does not by itself demonstrate durable real-world independence.',null],
 ['Resists human shutdown','Not established by this source set','A system continues operating despite a determined, technically capable attempt to stop it.','Statements about self-preservation, or a fictional threat, do not establish successful shutdown resistance.','agentic'],
 ['Strategically improves itself','Not established by this source set','A system directs repeated improvements to its own capabilities that enable further improvement.','AI-assisted coding is not enough to establish a self-sustaining improvement cycle.',null]
];
function ladderMarkup(){return `<section id="ladder"><div class="section-head"><div><h2>Concern ladder</h2></div><span class="small-note">Capability levels, not a forecast.</span></div><div class="ladder-layout"><div class="ladder-steps" role="group" aria-label="Levels of agent capability">${stages.map((s,i)=>`<button class="ladder-step ${i===1?'selected':''} ${i>2?'unestablished':''}" data-stage="${i}" aria-pressed="${i===1}"><span class="step-number">${i+1<10?'0':''}${i+1}</span><span>${s[0]}</span><span class="step-status">${i<2?'●':i===2?'◐':'○'}</span></button>`).join('')}</div><div id="stage-detail" class="stage-detail" aria-live="polite"></div></div><p class="small-note ladder-note">Evidence labels refer only to the five reports in this preview. “Not established” does not mean impossible or disproven. These stages need not occur in order.</p></section>`;}
function renderStage(index){const s=stages[index];if(!s)return;document.querySelectorAll('[data-stage]').forEach(b=>{const selected=Number(b.dataset.stage)===index;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',selected);});$('#stage-detail').innerHTML=`<span class="stage-big">${String(index+1).padStart(2,'0')}</span><p class="eyebrow">${s[1]}</p><h3>${s[0]}</h3><p>${s[2]}</p><div class="stage-why"><p class="eyebrow">IMPLICATIONS</p><p>${s[3]}</p></div>${s[4]?`<button class="text-link" data-event="${s[4]}">Related research ↗</button>`:'<p class="small-note">No supporting event is included in this preview.</p>'}`;}
function renderEvidence(){return `<section class="evidence-board"><div class="section-head"><div><h2>Evidence and interpretation</h2></div></div><div class="evidence-grid"><article><span class="evidence-label mint">01 / OBSERVED</span><p>Models completed multi-step tasks and sometimes made harmful choices in constructed settings.</p><button class="text-link" data-event="agentic">Source study ↗</button></article><article><span class="evidence-label amber">02 / INFERRED</span><p>More capable agents need stronger access limits and monitoring. This is a judgment based on the evidence.</p><a class="text-link" href="#methodology">Methodology ↗</a></article><article><span class="evidence-label muted">03 / SPECULATIVE</span><p>A system could one day operate indefinitely beyond human control. These sources do not establish that outcome.</p><button class="text-link" data-action="future-stage">Shutdown resistance ↗</button></article></div></section>`;}
function overview(){const o=data.outlook;main.innerHTML=heading('AI risk overview')+demoNote()+`<section class="outlook"><div class="outlook-main"><p class="eyebrow">FRONTIER AI RISK OUTLOOK <span class="small-note">· ${data.mode==='demo'?'EXAMPLE ASSESSMENT':'REVIEWED ASSESSMENT'}</span></p><div class="risk-title"><h2>${escape(o.level)}</h2><span class="trend">↗ ${escape(o.trend)}</span></div><div class="spectrum" aria-label="${data.mode==='demo'?'Illustrative concern level':'Concern level'}: ${escape(o.level)}">${['Guarded','Elevated','High','Severe','Critical'].map(x=>`<span class="${o.level===x?'selected':''}">${x}</span>`).join('')}</div><p>${escape(o.summary)}</p><button class="text-link" data-action="outlook">View supporting evidence <span>↗</span></button></div><aside class="outlook-aside"><span class="eyebrow">SIGNAL DIRECTION</span><button class="signal-row" data-signal="worsening"><span class="signal-symbol amber">↗</span><span><strong>Capability & risk</strong></span></button><button class="signal-row" data-signal="improving"><span class="signal-symbol mint">↘</span><span><strong>Safety & control</strong></span></button><div class="outlook-foot"><span class="small-note">A qualitative judgment.<br>Not a catastrophe probability.</span><a href="#methodology">How we assess ↗</a></div></aside></section><div class="changed-strip"><span class="eyebrow">LATEST NOTE</span><span>${escape(o.changed)}</span><button data-event="cross-lab" aria-label="Read latest research note">↗</button></div><section id="pathways"><div class="section-head"><div><h2>Risk pathways</h2></div></div><div class="pathway-grid">${pathwayCards()}</div></section>`+timelineMarkup()+ladderMarkup()+renderEvidence();
 $('#signal-filter').value=signal;filterEvents();renderStage(1);
}
function filterEvents(){const matches=data.events.filter(e=>(category==='All'||e.category===category)&&(signal==='all'||e.direction===signal));$('#event-list').innerHTML=matches.length?eventRows(matches):`<div class="empty-state"><h3>No notes in this selection.</h3><p>This small source set does not cover every category. No evidence here does not mean no risk.</p><button class="text-link" data-action="reset-filters">Show all research notes ↗</button></div>`;$('#result-count').textContent=`${matches.length} of ${data.events.length} notes · ${data.mode==='demo'?'Archived research preview':'Reviewed entries'}`;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('selected',b.dataset.filter===category);b.setAttribute('aria-pressed',b.dataset.filter===category);});}
function methodology(){main.innerHTML=heading('Methodology')+demoNote()+`<div class="method-layout"><aside class="method-nav"><a href="#methodology">Our approach</a><a href="#methodology-sources">Source register</a><a href="#glossary">Glossary</a></aside><article class="method-body"><section><h2>Scope</h2><p>Frontier Signal explains developments involving [[frontier model]] systems. It separates reported observations from interpretation and hypothetical futures, and tracks improvements in safety alongside increasing capabilities.</p><p>It does not estimate a precise probability of catastrophe. A qualitative category is an editorial judgment about capabilities, exposure, and safeguards—not a scientific consensus or a mechanical average.</p></section><section><h2>Risk levels</h2><div class="method-scale">${[['Guarded','Limited concerning evidence within the assessed scope; controls appear adequate for it.'],['Elevated','Meaningful warning signs warrant closer scrutiny of access and safeguards.'],['High','Substantial, relevant evidence of capability or control gaps; mitigation needs are urgent.'],['Severe','Repeated, consequential failures of safeguards in realistic conditions.'],['Critical','Strong evidence of sustained loss of effective control or comparably acute danger.']].map(([a,b])=>`<div><strong>${a}</strong><p>${b}</p></div>`).join('')}</div><p>These definitions are an editorial framework. No automatic score assigns the outlook. Every published rating requires a named reviewer, a dated rationale, supporting event IDs, and the evidence that would change the assessment.</p></section><section><h2>Evidence quality</h2><p>Each note identifies its source type and limitations. A developer report is useful primary evidence, but is not independent replication. A controlled experiment demonstrates behavior under its test conditions; it does not measure how often that behavior occurs in everyday use.</p><p>Confidence in an observation is separate from how concerning its implications may be. We avoid treating a model’s words, a simulation, or a single demonstration as proof of durable autonomous behavior.</p></section><section><h2>Editorial review</h2><ol class="review-steps"><li><strong>Gather</strong><span>Collect the original report and record its date, conditions, and limitations.</span></li><li><strong>Interpret</strong><span>Draft the observation, meaning, counterevidence, and escalation criteria separately.</span></li><li><strong>Review</strong><span>A human verifies claims and sources and records approval.</span></li><li><strong>Publish</strong><span>Approved changes enter the versioned source. The site updates from the approved release.</span></li></ol><p>Draft analysis is not a live risk update. This launch is a demonstration edition using a small, historical research set; no ChatGPT automation is currently connected. The outlook and pathway ratings are illustrative and have no claimed human approval.</p></section><section><h2>Assessment revisions</h2><p>A future update should identify new evidence, assumptions that strengthened or weakened, counterevidence, and remaining uncertainty. Changes to the overall outlook must be reviewed separately from individual event summaries.</p><div class="revision"><span class="pill">Preview 001</span><p>Initial interface and source set. No historical change in a live assessment is claimed.</p></div></section><section id="methodology-sources"><h2>Sources</h2><p>These five reports span February–August 2025. The selection is intentionally small and is not representative of all current research or all six pathways.</p>${data.events.map(e=>`<div class="source-record"><p class="small-note">${date(e.date)} · ${escape(e.evidence)}</p>${sources(e)}</div>`).join('')}</section><section id="glossary"><h2>Glossary</h2><p>Underlined terms throughout the site open a short explanation. The Simplified vocabulary switch changes the language used in timeline summaries.</p><div class="glossary-grid">${Object.keys(glossary).map(t=>`<button data-term="${escape(t)}">${escape(t)} <span>↗</span></button>`).join('')}</div></section></article></div>`;}
function route(){if(!data)return;const hash=location.hash.slice(1)||'overview';const isMethod=['methodology','methodology-sources','glossary'].includes(hash);document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash===`#${isMethod?'methodology':hash}`));if(isMethod)methodology();else overview();document.title=`${isMethod?'Methodology':'AI risk overview'} — Frontier Signal`;requestAnimationFrame(()=>{if(hash==='overview'||hash==='methodology')window.scrollTo(0,0);else document.getElementById(hash)?.scrollIntoView();});}
function setBeginner(value){beginner=value;$('#beginner-toggle').setAttribute('aria-checked',beginner);try{localStorage.setItem('frontier-simplified-vocabulary',String(beginner));}catch{}if($('#event-list'))filterEvents();}
document.addEventListener('click',event=>{
 const b=event.target.closest('button,a');if(!b)return;
 if(b.dataset.event){returnDialog=null;showEvent(b.dataset.event);}
 else if(b.dataset.worry){returnDialog=null;showEvent(b.dataset.worry,true);}
 else if(b.dataset.pathway){returnDialog=null;showPathway(b.dataset.pathway);}
 else if(b.dataset.term)showTerm(b.dataset.term);
 else if(b.dataset.stage!==undefined)renderStage(Number(b.dataset.stage));
 else if(b.dataset.filter){category=b.dataset.filter;filterEvents();}
 else if(b.dataset.signal){signal=b.dataset.signal;category='All';$('#signal-filter').value=signal;filterEvents();location.hash='timeline';}
 else if(b.dataset.action==='outlook'){returnDialog=null;showOutlook();}
 else if(b.dataset.action==='back-dialog'){const previous=returnDialog;returnDialog=null;openDialog(previous);}
 else if(b.dataset.action==='reset-filters'){category='All';signal='all';$('#signal-filter').value=signal;filterEvents();}
 else if(b.dataset.action==='future-stage'){$('#ladder').scrollIntoView();renderStage(7);}
 else if(b.dataset.action==='retry')location.reload();
 if(b.hasAttribute('data-close'))dialog.close();
});
$('#beginner-toggle').onclick=()=>setBeginner(!beginner);
$('.close-dialog').onclick=()=>dialog.close();
dialog.addEventListener('close',()=>{returnDialog=null;});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
document.addEventListener('change',e=>{if(e.target.id==='signal-filter'){signal=e.target.value;filterEvents();}});
window.addEventListener('hashchange',route);
try {
 const responses=await Promise.all(['signals','glossary'].map(name=>fetch(`./data/${name}.json`)));
 if(responses.some(r=>!r.ok))throw new Error('Research files unavailable');
 [data,glossary]=await Promise.all(responses.map(r=>r.json()));
 data.events.sort((a,b)=>b.date.localeCompare(a.date));
 $('#edition-label').textContent=data.mode==='demo'?'RESEARCH PREVIEW · 2025':`REVIEWED · ${date(data.asOf)}`;
 setBeginner(beginner);route();
} catch(error) {
 main.innerHTML=`<div class="empty-state"><p class="eyebrow">FRONTIER SIGNAL</p><h1>The research notes couldn’t load.</h1><p>Please check your connection and try again.</p><button class="text-link" data-action="retry">Try again ↗</button></div>`;
 console.error('Frontier Signal could not load its research files.',error);
}
